PROGRAM ST510_ETIKETTERING
VAR
    steg        : INT := 0;
    tmrLas      : TON;
    trigReset   : R_TRIG;
    trigPart    : R_TRIG;
    trigDone    : R_TRIG;
    cntUnder    : CTU;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xLasklar    : BOOL := FALSE;
    xOgiltig    : BOOL := FALSE;
    xUnderkand  : BOOL := FALSE;
    xGodkand    : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. *)
trigReset(CLK := SYS_RESET);
trigPart(CLK := ST510_PEC_PART);
trigDone(CLK := ST510_SCN_DONE);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* --- larmkallorna samlas fore domen --- *)

(* Verifierarens svar lases pa lasningens egen flank, inte pa niva: ett svar
   som ligger kvar hor till foregaende kartong. *)
xLasklar := trigDone.Q AND ST510_SCN_TRIG;
xOgiltig := xLasklar AND (ST510_SCN_GRADE > 4.0 OR ST510_SCN_GRADE < 0.0);
xUnderkand := xLasklar AND (NOT xOgiltig) AND (ST510_SCN_GRADE < 1.5);
xGodkand := xLasklar AND (NOT xOgiltig) AND (ST510_SCN_GRADE >= 1.5);

(* ISO/IEC 15416 gar fran 4,0 till 0,0. Ett betyg utanfor skalan ar ett
   lasarfel, inte en bra etikett, och far aldrig lasas som godkant. *)
IF xOgiltig THEN
    xLarm := TRUE;
END_IF;

(* Tre underkanda etiketter i rad ar inte tre olyckor utan ett slut eller
   smutsigt skrivhuvud. Raknaren nollstalls av varje godkand etikett. *)
cntUnder(CU := xUnderkand, R := xGodkand OR trigReset.Q, PV := 3);
IF cntUnder.Q THEN
    xLarm := TRUE;
END_IF;

(* Lasvakten. Verifieraren bedomer pa 80 ms; kommer inget svar inom 0,50 s har
   lasningen uteblivit. *)
tmrLas(IN := ST510_SCN_TRIG, PT := T#500ms);

IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    ST510_LBL_PRINT := FALSE;
    ST510_LBL_APPLY := FALSE;
    ST510_SCN_TRIG := FALSE;
    ST510_PSH_REJ := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST510_PSH_REJ := FALSE;
            (* Cykeln startar pa kartongens framkant, inte pa narvaron: en
               kartong som star kvar framfor fotocellen far inte utlosa en
               ny etikett. *)
            IF trigPart.Q THEN
                ST510_LBL_PRINT := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Stampeln gar forst nar skrivaren har etiketten pa dynan. *)
            IF ST510_PRN_READY THEN
                ST510_LBL_PRINT := FALSE;
                ST510_LBL_APPLY := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST510_LBL_APPLIED THEN
                ST510_LBL_APPLY := FALSE;
                ST510_SCN_TRIG := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST510_SCN_DONE THEN
                ST510_SCN_TRIG := FALSE;
                IF ST510_SCN_GRADE < 1.5 THEN
                    ST510_PSH_REJ := TRUE;
                    steg := 4;
                ELSE
                    steg := 6;
                END_IF;
            ELSIF tmrLas.Q THEN
                (* Lasningen uteblev. Ingen kartong far passera olast. *)
                ST510_SCN_TRIG := FALSE;
                ST510_PSH_REJ := TRUE;
                steg := 4;
            END_IF;
        4:
            IF NOT ST510_PSH_HOME THEN
                ST510_PSH_REJ := FALSE;
                steg := 5;
            END_IF;
        5:
            IF ST510_PSH_HOME THEN
                steg := 0;
            END_IF;
        6:
            IF NOT ST510_PEC_PART THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Utan tryckluft finns ingen kraft i cylindern. Ett kommando som ligger kvar
   slar ut kartongen forst nar luften kommer tillbaka. *)
IF NOT AIR_OK THEN
    ST510_PSH_REJ := FALSE;
END_IF;

ST510_CNV_RUN := xDriftsklar;
END_PROGRAM

